use std::ffi::c_int;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

const SIGUSR1: c_int = 10; // Linux numbering
const SIGTERM: c_int = 15;

unsafe extern "C" {
    fn signal(sig: c_int, handler: extern "C" fn(c_int)) -> usize;
    fn raise(sig: c_int) -> c_int;
}

static SHUT_DOWN: AtomicBool = AtomicBool::new(false);
static USR1_COUNT: AtomicUsize = AtomicUsize::new(0);

extern "C" fn handle_sigterm(_sig: c_int) {
    SHUT_DOWN.store(true, Ordering::SeqCst);
}

extern "C" fn handle_sigusr1(_sig: c_int) {
    USR1_COUNT.fetch_add(1, Ordering::SeqCst);
}

fn main() {
    unsafe {
        signal(SIGTERM, handle_sigterm);
        signal(SIGUSR1, handle_sigusr1);
    }

    let mut i = 0;
    loop {
        i += 1;
        if i % 3 == 0 {
            unsafe { raise(SIGUSR1) };
        }
        if i == 10 {
            unsafe { raise(SIGTERM) }; // as if someone ran `kill <pid>`
        }
        if SHUT_DOWN.load(Ordering::SeqCst) {
            break;
        }
    }
    println!("stopped after {i} iterations, SIGUSR1 seen {} times", USR1_COUNT.load(Ordering::SeqCst));
}

